import { build } from "esbuild";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(root, "src", "scan", "domAccessibilityApiBundle.ts");
const noticePath = path.join(root, "THIRD_PARTY_NOTICES.md");
const version = "0.7.1";
const check = process.argv.includes("--check");
const dependencyPath = path.join(root, "node_modules", "dom-accessibility-api");
const dependency = JSON.parse(await readFile(path.join(dependencyPath, "package.json"), "utf8"));
if (dependency.version !== version) throw new Error(`expected dom-accessibility-api@${version}, found ${dependency.version || "unknown"}`);
const license = (await readFile(path.join(dependencyPath, "LICENSE.md"), "utf8")).trimEnd();

const result = await build({
	absWorkingDir: root,
	entryPoints: ["dom-accessibility-api"],
	bundle: true,
	write: false,
	format: "iife",
	globalName: "BrowserPilotDomAccessibilityApi",
	platform: "browser",
	target: ["chrome120"],
	minify: true,
	legalComments: "none",
});
const bundle = result.outputFiles[0]?.text.trimEnd();
if (!bundle) throw new Error("dom-accessibility-api bundle generation produced no output");
const source = `// Generated by scripts/generate-dom-accessibility-bundle.mjs from dom-accessibility-api@${version} (MIT). Do not edit.\n// See THIRD_PARTY_NOTICES.md.\nexport const DOM_ACCESSIBILITY_API_BUNDLE: string = ${JSON.stringify(bundle)};\n`;
const notice = `# Third-Party Notices\n\n## dom-accessibility-api ${version}\n\nSource: https://github.com/eps1lon/dom-accessibility-api\n\nBrowser Pilot includes a generated browser bundle of \`dom-accessibility-api\` under the MIT License:\n\n${license}\n`;

if (check) {
	if (await readFile(outputPath, "utf8") !== source) throw new Error("generated accessibility bundle is stale; run npm run generate:dom-accessibility");
	if (await readFile(noticePath, "utf8") !== notice) throw new Error("THIRD_PARTY_NOTICES.md is stale; run npm run generate:dom-accessibility");
	console.log("verified generated accessibility bundle and third-party notice");
} else {
	await writeFile(outputPath, source, "utf8");
	await writeFile(noticePath, notice, "utf8");
	console.log("generated accessibility bundle and third-party notice");
}
